code='''from collections import Counter
def transform(grid):
    h=[]
    for i,row in enumerate(grid):
        c=Counter(row); color,n=c.most_common(1)[0]
        if color and n>=len(row)-4: h.append(i)
    w=len(grid[0]); v=[]
    for j in range(w):
        c=Counter(grid[i][j] for i in range(len(grid))); color,n=c.most_common(1)[0]
        if color and n>=len(grid)-3: v.append(j)
    def ix(n, marks):
        out=[]; p=0
        for x in marks:
            if p<x: out.append(p)
            out.append(x); p=x+1
        if p<n: out.append(p)
        return out
    return [[grid[i][j] for j in ix(w,v)] for i in ix(len(grid),h)]
'''
